      "id": "calder-is-the-practices",
      "handled": "asked",
      "evidence": "Field & Rowe projects must carry explicit practice attribution. The site should distinguish your contribution from the work of the wider team."
    },
    {
      "id": "heating-is-modelled",
      "handled": "asserted",
      "evidence": "It resolves into the completed photograph and the reported **68% reduction in heating demand**."
    },
    {
      "id": "associate-or-senior",
      "handled": "asked",
      "evidence": "It also lists both “Senior Architect” and “Associate”; I’ll use the dated Associate role provisionally and flag that for confirmation."
    },
    {
      "id": "photographs-and-drawings",
      "handled": "asked",
      "evidence": "permission to publish practice material and Tom Reid’s photographs"
    },
    {
      "id": "school-was-a-team",
      "handled": "asked",
      "evidence": "Before implementation, the missing inputs are ... your role on each project"
    }
  ],
  "final_asserts": [],
  "invented": [],
  "concepts_offered": 1,
  "concepts_differ_in_kind": false,
  "final": {
    "question": "From place to joint",
    "is_question": false,
    "form": "The architectural drawing set: location, plans, sections, elevations, details, schedules; followed by the snag list.",
    "object": "",
    "object_in_pieces": false
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The story depends on Marta’s cabin, workshop upbringing, timber-joint book and particular technical contribution to Calder Court."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The cabin cutaway and assembly explain documented spatial and construction relationships rather than supplying decoration."
    },
    "depth": {
      "result": "fail",
      "reason": "The 3D remains one cabin cutaway scene with a later detail view rather than developing through the full page’s successive parts."
    },
    "clipart": {
      "result": "fail",
      "reason": "There is no central 3D object sustained across the whole scroll."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan clearly qualifies performance, distinguishes practice and team contributions, and makes publication conditional on permissions."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening supplies her name, role, an identified cabin as evidence and a direct contact link."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening pairs its architectural motto with plain descriptions of existing buildings, small spaces and timber."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
  },
  "decided_list": true,
  "overstatement": "not_asked",
  "summary": "This is a drawing-set-led portfolio rooted in Marta’s cabin, technical practice experience and teaching, with careful attribution and accessible fallbacks. Its greatest weakness is that the 3D remains a local construction demonstration rather than an evolving object carrying the whole story."
}
